pub const fn ahri_qmin(ctx: &Ctx) -> f32 {
    35f32 + 25f32 * (-1f32 + ctx.q_level) + ctx.ability_power / 2f32
}

pub const fn ahri_qmax(ctx: &Ctx) -> f32 {
    70f32
        + 50f32 * (-1f32 + ctx.q_level)
        + ctx.ability_power / 2f32
        + 0.5 * ctx.ability_power * ctx.magic_multiplier
}

pub const fn ahri_w1(ctx: &Ctx) -> f32 {
    8f32 * (1f32 + 0.02 * ctx.ability_power + ctx.w_level)
}

pub const fn ahri_wmin(ctx: &Ctx) -> f32 {
    20f32 * (1f32 + 0.02 * ctx.ability_power + ctx.w_level)
}

pub const fn ahri_wmax(ctx: &Ctx) -> f32 {
    36f32 * (1f32 + 0.02 * ctx.ability_power + ctx.w_level)
}

pub const fn ahri_e(ctx: &Ctx) -> f32 {
    40f32 * (1f32 + 0.02125 * ctx.ability_power + ctx.e_level)
}

pub const fn ahri_rmin(ctx: &Ctx) -> f32 {
    25f32 * (3f32 + 0.014 * ctx.ability_power + 2f32 * (-1f32 + ctx.r_level))
}

pub const fn ahri_rmax(ctx: &Ctx) -> f32 {
    75f32 * (3f32 + 0.014 * ctx.ability_power + 2f32 * (-1f32 + ctx.r_level))
}

